void mainImage( out vec4 O, vec2 u )
{
    vec2 U = u/R.y;
    O*=0.;
    for( int i; i < N*N; i++)                                                               // display particles
        if(taxi(U,P(i).xy)<.005){O=col(P(i).z);break;}

    if (U.y<.08) O = O*.3 + max(1.2 - R.y* abs( T(vec2(u.x,N))/float(N*N)*.08 - U.y ),0.);  // display stats
}

int N = 48; // NxN particles
#define R    iResolution.xy
#define T(u) texelFetch( iChannel0, ivec2(u), 0 )
#define P(i) T(vec2(i%N,i/N))
float taxi(vec2 a, vec2 b){return abs(a.x-b.x)+abs(a.y-b.y);}
vec4 col(float x){x=mod(x,3.);return vec4(x==0.?1.:0.,x==1.?1.:0.,x==2.?1.:0.,0.);}

#define H   fract(1e4*sin((iTime+float(p))*R))

vec2 hash23(vec3 p3)
{
	p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx+33.33);
    return fract((p3.xx+p3.yz)*p3.zy);
}
//random hash from Dave_Hoskins https://www.shadertoy.com/view/4djSRW

void mainImage( out vec4 O, vec2 u )
{
    O*=0.; if ( int(u.y) == N )                                  // --- stats
        if (int(u)<1) for(int i; i < N*N; i++) O[int(P(i).z)]++; // compute
        else          O =  T(vec2(u.x-1.,N));                    //  scroll

    if ( int(u) >= N || int(u.y) >= N ) return;                  // simulates NxN particles
    int p = int(u) + N*int(u.y);                                 // particle id
    O = P(p);                                                    // load previous state

    float d = 9., l, v;                                          // --- manage particles
    for( int i; i < N*N; i++ ){                                   
        if ( i != p && mod(O.z-P(i).z,3.)==2. && taxi(O.xy,P(i).xy)<.01){
        O.z=P(i).z; break;
        }}


    O.xy = mod(O.xy + (H-.5)/R.y *iTimeDelta*90. , R/R.y);       // random displacement

    if (iFrame<1)                                                // --- init: random location and type
        O.xy = hash23(vec3(u,iDate[3]))*R/R.y, O.z = floor(mod(O.x*R.x,3.));            // type = 0:rock 1:paper 2:scissor
}
